mapper.select:
select ual.*, ap.name as uri_name
from user_admin_log ual
left join auth_permission ap on ual.uri = ap.uri


        and ual.parent_address = #{parentAddress}


        and ual.create_time >= #{startTime}


        and #{endTime} >= ual.create_time


        and (
        ual.address = #{vague}
        or ual.parent_address = #{vague}
        or ap.name like CONCAT('%', #{vague}, '%')
        )


order by id desc
